START TRANSACTION;

INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (349, 'reglas_intro_cards', 'cards', '[{"icon": "BookOpen", "title": "Reglas USGA / FMG", "body": "Se jugará bajo las reglas que rigen la U.S.G.A., adoptadas por la Federación Mexicana de Golf, y las reglas locales del Club. Las condiciones y reglas locales se publican en las pantallas y se entregan junto con la tarjeta de score."}, {"icon": "Scale", "title": "Sistema de Hándicap", "body": "Se utiliza el hándicap GHIN vigente registrado en la FMG, publicado al 15 de mayo de 2026 (el más bajo si el jugador pertenece a dos o más clubes). Las categorías con ventaja juegan al 85% del H.I. (Estrellal al 100%)."}, {"icon": "ShieldCheck", "title": "Comité de Reglas", "body": "Las controversias sobre la aplicación de las reglas serán resueltas por el Director de Reglas y su fallo será definitivo. Las decisiones del Comité Organizador y del Comité de Reglas son inapelables."}]', 1)
ON DUPLICATE KEY UPDATE
  section_type = 'cards',
  content = '[{"icon": "BookOpen", "title": "Reglas USGA / FMG", "body": "Se jugará bajo las reglas que rigen la U.S.G.A., adoptadas por la Federación Mexicana de Golf, y las reglas locales del Club. Las condiciones y reglas locales se publican en las pantallas y se entregan junto con la tarjeta de score."}, {"icon": "Scale", "title": "Sistema de Hándicap", "body": "Se utiliza el hándicap GHIN vigente registrado en la FMG, publicado al 15 de mayo de 2026 (el más bajo si el jugador pertenece a dos o más clubes). Las categorías con ventaja juegan al 85% del H.I. (Estrellal al 100%)."}, {"icon": "ShieldCheck", "title": "Comité de Reglas", "body": "Las controversias sobre la aplicación de las reglas serán resueltas por el Director de Reglas y su fallo será definitivo. Las decisiones del Comité Organizador y del Comité de Reglas son inapelables."}]',
  enabled = 1,
  updated_at = CURRENT_TIMESTAMP;

INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (349, 'reglas_locales', 'accordion', '[{"titulo": "Reglas de juego", "contenido": "Las reglas del Torneo serán las que rigen en la U.S.G.A. adoptadas por la Federación Mexicana de Golf y las reglas locales del Club. Las condiciones de la competencia y reglas locales se publican en las pantallas y se entregan junto con las tarjetas de score."}, {"titulo": "Resolución de controversias", "contenido": "Las controversias sobre la aplicación de las reglas serán resueltas por el Director de Reglas y su fallo será definitivo. Las decisiones del Comité Organizador y del Comité de Reglas son inapelables."}, {"titulo": "Cambios en rondas y días de juego", "contenido": "Las rondas y días de juego están sujetas a cambios sin previo aviso para beneficio general del Torneo. En caso de condiciones climatológicas adversas, se tomará como primer criterio rondas de 9 hoyos cuando aplique."}, {"titulo": "Aceptación y siembra de jugadores", "contenido": "El Comité Organizador se reserva el derecho de aceptar a cualquier jugador o sembrarlo en otra categoría. Un jugador sin GHIN deberá firmar carta aceptando cualquier reclamación por parte de otro jugador y solo podrá participar por premios de habilidades, O´yes, Hole In One y rifas, renunciando a la competencia principal."}, {"titulo": "Entrega de tarjetas de score", "contenido": "Los jugadores son responsables de entregar sus tarjetas firmadas con el número de golpes sin ventaja (Gross) escritos claramente en cada hoyo en la tarjeta de score oficial. La tarjeta debe estar firmada por el anotador."}, {"titulo": "Investigación por scores irregulares", "contenido": "Si un jugador tira en la suma de los dos días de competencia -8 golpes de su hándicap y existe reclamación oficial por escrito, el Comité Organizador investigará al jugador consultando las rondas registradas en GHIN de enero a abril 2026. Si no tiene scores suficientes que avalen un hándicap real y actualizado, podrá ser descalificado. El Comité de Reglas decidirá y su decisión será definitiva."}, {"titulo": "Cortes y categorías", "contenido": "Habrá corte en todas las categorías de Caballeros después de la 2ª ronda. Las 5 categorías de Damas no tienen corte. Si por cuestiones climatológicas no se logran jugar dos rondas de 18 hoyos, el Comité Organizador decidirá a cuántos hoyos se hará el corte. Si una categoría alcanza el número máximo de jugadores, se cerrará y los siguientes entrarán a lista de espera."}, {"titulo": "Restricción de acceso a menores", "contenido": "Durante el desarrollo del Torneo queda restringido el acceso a menores de edad a la Casa Club, eventos sociales y premiación. Solo se autoriza el acceso a menores que jueguen en la categoría Premier de Caballeros y 1ª Categoría de Damas."}]', 1)
ON DUPLICATE KEY UPDATE
  section_type = 'accordion',
  content = '[{"titulo": "Reglas de juego", "contenido": "Las reglas del Torneo serán las que rigen en la U.S.G.A. adoptadas por la Federación Mexicana de Golf y las reglas locales del Club. Las condiciones de la competencia y reglas locales se publican en las pantallas y se entregan junto con las tarjetas de score."}, {"titulo": "Resolución de controversias", "contenido": "Las controversias sobre la aplicación de las reglas serán resueltas por el Director de Reglas y su fallo será definitivo. Las decisiones del Comité Organizador y del Comité de Reglas son inapelables."}, {"titulo": "Cambios en rondas y días de juego", "contenido": "Las rondas y días de juego están sujetas a cambios sin previo aviso para beneficio general del Torneo. En caso de condiciones climatológicas adversas, se tomará como primer criterio rondas de 9 hoyos cuando aplique."}, {"titulo": "Aceptación y siembra de jugadores", "contenido": "El Comité Organizador se reserva el derecho de aceptar a cualquier jugador o sembrarlo en otra categoría. Un jugador sin GHIN deberá firmar carta aceptando cualquier reclamación por parte de otro jugador y solo podrá participar por premios de habilidades, O´yes, Hole In One y rifas, renunciando a la competencia principal."}, {"titulo": "Entrega de tarjetas de score", "contenido": "Los jugadores son responsables de entregar sus tarjetas firmadas con el número de golpes sin ventaja (Gross) escritos claramente en cada hoyo en la tarjeta de score oficial. La tarjeta debe estar firmada por el anotador."}, {"titulo": "Investigación por scores irregulares", "contenido": "Si un jugador tira en la suma de los dos días de competencia -8 golpes de su hándicap y existe reclamación oficial por escrito, el Comité Organizador investigará al jugador consultando las rondas registradas en GHIN de enero a abril 2026. Si no tiene scores suficientes que avalen un hándicap real y actualizado, podrá ser descalificado. El Comité de Reglas decidirá y su decisión será definitiva."}, {"titulo": "Cortes y categorías", "contenido": "Habrá corte en todas las categorías de Caballeros después de la 2ª ronda. Las 5 categorías de Damas no tienen corte. Si por cuestiones climatológicas no se logran jugar dos rondas de 18 hoyos, el Comité Organizador decidirá a cuántos hoyos se hará el corte. Si una categoría alcanza el número máximo de jugadores, se cerrará y los siguientes entrarán a lista de espera."}, {"titulo": "Restricción de acceso a menores", "contenido": "Durante el desarrollo del Torneo queda restringido el acceso a menores de edad a la Casa Club, eventos sociales y premiación. Solo se autoriza el acceso a menores que jueguen en la categoría Premier de Caballeros y 1ª Categoría de Damas."}]',
  enabled = 1,
  updated_at = CURRENT_TIMESTAMP;

INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (349, 'reglamento_local', 'accordion', '[{"titulo": "Caballeros — Campeonato", "contenido": "Stroke Play sin ventaja. 54 hoyos con corte a 36. Edad: 16 años o más. Rango HCP Índice: +5.0 a 1.2. Tees Negras. Cupo: 36 jugadores. Pasan al corte 16."}, {"titulo": "Caballeros — Premier", "contenido": "Stroke Play sin ventaja. 54 hoyos con corte a 36. Edad: 16 años o más. Rango HCP Índice: 1.3 a 3.0. Tees Azules. Cupo: 36. Corte: 16."}, {"titulo": "Caballeros — AA", "contenido": "Stroke Play sin ventaja. 54 hoyos con corte a 36. Edad: 18 años o más. Rango: 3.1 a 6.3. Tees Azules. Cupo: 36. Corte: 16."}, {"titulo": "Caballeros — A", "contenido": "Stroke Play sin ventaja. 54 hoyos con corte a 36. Edad: 18 años o más. Rango: 6.4 a 10.5. Tees Blancas. Cupo: 56. Corte: 16."}, {"titulo": "Caballeros — B", "contenido": "Stableford 85% de ventaja. 54 hoyos con corte a 36. Edad: 18 años o más. Rango: 10.6 a 15.8. Tees Blancas. Cupo: 56. Corte: 16."}, {"titulo": "Caballeros — C", "contenido": "Stableford 85% de ventaja. 54 hoyos con corte a 36. Edad: 18 años o más. Rango: 15.9 a 22.0. Tees Blancas. Cupo: 80. Corte: 16."}, {"titulo": "Caballeros — D", "contenido": "Stableford 85% de ventaja. 54 hoyos con corte a 36. Edad: 18 años o más. Rango: 22.1 a 32.7. Tees Blancas. Cupo: 80. Corte: 16."}, {"titulo": "Seniors (50 a 60 años)", "contenido": "Stableford 85% de ventaja. 54 hoyos con corte a 36. Rango: 0 a 32.2. Tees Blancas. Cupo: 24. Corte: 16. Deben tener 50 a 60 años cumplidos al 15 de mayo de 2026."}, {"titulo": "Super Seniors (61 años o más)", "contenido": "Stableford 85% de ventaja. 54 hoyos con corte a 36. Rango: 0 a 32.2. Tees Doradas. Cupo: 24. Corte: 16. Deben tener 61 años cumplidos al 15 de mayo de 2026."}, {"titulo": "Damas — 1ª Categoría", "contenido": "Stroke Play 85% de ventaja. 54 hoyos sin corte. Edad: 16 años o más. Rango: +5.0 a 14.8. Tees Rojas. Cupo: 21. Se permite jugadoras de 14 años en adelante con registros en torneos juveniles con scores por debajo de 84 golpes."}, {"titulo": "Damas — 2ª, 3ª y 4ª", "contenido": "Stableford 85% de ventaja. 54 hoyos sin corte. Edad: 18 años o más. Tees Rojas. Cupo: 21 por categoría. Rangos: 2ª (14.9 a 23.0), 3ª (23.1 a 28.5), 4ª (28.6 a 35.8)."}, {"titulo": "Damas — Estrellal", "contenido": "Stableford 100% de ventaja. 54 hoyos sin corte. Edad: 16 años o más. 36 sin H.I. Tees especiales. Cupo: 15. Si no alcanza el cupo mínimo de 9 jugadoras, se registrarán en la categoría que les corresponda por hándicap. Las jugadoras deben ser autorizadas por los profesionales de golf en base a su nivel de principiantes."}, {"titulo": "Programación de salidas", "contenido": "Las salidas se programan con base a la competencia Neto cuando aplique. Para categorías que juegan GROSS y NETO, las salidas se programan en base al GROSS. Una jugadora no puede recibir trofeo Gross y Neto a la vez en la 1ª Categoría de Damas; sólo se puede ser acreedora al 1er lugar Gross."}, {"titulo": "Categoría con menos de 9 participantes", "contenido": "Se declarará desierta una categoría si tiene menos de 9 participantes. La fecha límite para definir esto es el jueves 25 de junio de 2026. El Comité podrá fusionar la categoría con alguna otra o declararla desierta. La ronda estipulada será de 9 hoyos."}, {"titulo": "Cambios de horario o día", "contenido": "Ningún jugador podrá solicitar cambio de horario o día de juego."}, {"titulo": "Cortes — ausencia a ronda final", "contenido": "El jugador que no pueda asistir a la ronda final por cualquier motivo deberá avisar a la Oficina de Golf o al Comité Organizador inmediatamente después de terminar su 2ª ronda, para asignarle el retiro del Torneo y permitir que el siguiente en la lista juegue. Quien entregue su tarjeta y no se retire pasará el corte; si no se presenta a la final, ningún jugador podrá tomar su lugar. Un jugador que no pasó el corte oficialmente no podrá participar en la ronda final por ningún motivo. Quien no dé aviso, será asignado por el Comité a la categoría que su hándicap original indique (o a la categoría Senior correspondiente si tiene más de 50 años)."}]', 1)
ON DUPLICATE KEY UPDATE
  section_type = 'accordion',
  content = '[{"titulo": "Caballeros — Campeonato", "contenido": "Stroke Play sin ventaja. 54 hoyos con corte a 36. Edad: 16 años o más. Rango HCP Índice: +5.0 a 1.2. Tees Negras. Cupo: 36 jugadores. Pasan al corte 16."}, {"titulo": "Caballeros — Premier", "contenido": "Stroke Play sin ventaja. 54 hoyos con corte a 36. Edad: 16 años o más. Rango HCP Índice: 1.3 a 3.0. Tees Azules. Cupo: 36. Corte: 16."}, {"titulo": "Caballeros — AA", "contenido": "Stroke Play sin ventaja. 54 hoyos con corte a 36. Edad: 18 años o más. Rango: 3.1 a 6.3. Tees Azules. Cupo: 36. Corte: 16."}, {"titulo": "Caballeros — A", "contenido": "Stroke Play sin ventaja. 54 hoyos con corte a 36. Edad: 18 años o más. Rango: 6.4 a 10.5. Tees Blancas. Cupo: 56. Corte: 16."}, {"titulo": "Caballeros — B", "contenido": "Stableford 85% de ventaja. 54 hoyos con corte a 36. Edad: 18 años o más. Rango: 10.6 a 15.8. Tees Blancas. Cupo: 56. Corte: 16."}, {"titulo": "Caballeros — C", "contenido": "Stableford 85% de ventaja. 54 hoyos con corte a 36. Edad: 18 años o más. Rango: 15.9 a 22.0. Tees Blancas. Cupo: 80. Corte: 16."}, {"titulo": "Caballeros — D", "contenido": "Stableford 85% de ventaja. 54 hoyos con corte a 36. Edad: 18 años o más. Rango: 22.1 a 32.7. Tees Blancas. Cupo: 80. Corte: 16."}, {"titulo": "Seniors (50 a 60 años)", "contenido": "Stableford 85% de ventaja. 54 hoyos con corte a 36. Rango: 0 a 32.2. Tees Blancas. Cupo: 24. Corte: 16. Deben tener 50 a 60 años cumplidos al 15 de mayo de 2026."}, {"titulo": "Super Seniors (61 años o más)", "contenido": "Stableford 85% de ventaja. 54 hoyos con corte a 36. Rango: 0 a 32.2. Tees Doradas. Cupo: 24. Corte: 16. Deben tener 61 años cumplidos al 15 de mayo de 2026."}, {"titulo": "Damas — 1ª Categoría", "contenido": "Stroke Play 85% de ventaja. 54 hoyos sin corte. Edad: 16 años o más. Rango: +5.0 a 14.8. Tees Rojas. Cupo: 21. Se permite jugadoras de 14 años en adelante con registros en torneos juveniles con scores por debajo de 84 golpes."}, {"titulo": "Damas — 2ª, 3ª y 4ª", "contenido": "Stableford 85% de ventaja. 54 hoyos sin corte. Edad: 18 años o más. Tees Rojas. Cupo: 21 por categoría. Rangos: 2ª (14.9 a 23.0), 3ª (23.1 a 28.5), 4ª (28.6 a 35.8)."}, {"titulo": "Damas — Estrellal", "contenido": "Stableford 100% de ventaja. 54 hoyos sin corte. Edad: 16 años o más. 36 sin H.I. Tees especiales. Cupo: 15. Si no alcanza el cupo mínimo de 9 jugadoras, se registrarán en la categoría que les corresponda por hándicap. Las jugadoras deben ser autorizadas por los profesionales de golf en base a su nivel de principiantes."}, {"titulo": "Programación de salidas", "contenido": "Las salidas se programan con base a la competencia Neto cuando aplique. Para categorías que juegan GROSS y NETO, las salidas se programan en base al GROSS. Una jugadora no puede recibir trofeo Gross y Neto a la vez en la 1ª Categoría de Damas; sólo se puede ser acreedora al 1er lugar Gross."}, {"titulo": "Categoría con menos de 9 participantes", "contenido": "Se declarará desierta una categoría si tiene menos de 9 participantes. La fecha límite para definir esto es el jueves 25 de junio de 2026. El Comité podrá fusionar la categoría con alguna otra o declararla desierta. La ronda estipulada será de 9 hoyos."}, {"titulo": "Cambios de horario o día", "contenido": "Ningún jugador podrá solicitar cambio de horario o día de juego."}, {"titulo": "Cortes — ausencia a ronda final", "contenido": "El jugador que no pueda asistir a la ronda final por cualquier motivo deberá avisar a la Oficina de Golf o al Comité Organizador inmediatamente después de terminar su 2ª ronda, para asignarle el retiro del Torneo y permitir que el siguiente en la lista juegue. Quien entregue su tarjeta y no se retire pasará el corte; si no se presenta a la final, ningún jugador podrá tomar su lugar. Un jugador que no pasó el corte oficialmente no podrá participar en la ronda final por ningún motivo. Quien no dé aviso, será asignado por el Comité a la categoría que su hándicap original indique (o a la categoría Senior correspondiente si tiene más de 50 años)."}]',
  enabled = 1,
  updated_at = CURRENT_TIMESTAMP;

INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (349, 'desempates', 'accordion', '[{"titulo": "Desempate por el primer lugar", "contenido": "Se jugará en el campo iniciando en el hoyo que designe el Comité. Si hay triple empate o más, el primer lugar se decide por juego en el campo (sólo un ganador absoluto) y las posiciones siguientes por comparación de tarjetas. Si no hay luz natural o las condiciones climatológicas impiden jugar en el campo, el primer lugar se decide por comparación de tarjetas. Si la competencia es Gross y Neto, sólo el trofeo Gross procede a juego en el campo; el 1er lugar Neto se define por comparación de tarjetas."}, {"titulo": "Desempate por segundo lugar en adelante y corte (Regla 5A — comparación de tarjetas)", "contenido": "Gana el jugador con la mejor ronda del último día. Si persiste el empate: mejor score en los hoyos 10 al 18; luego en 13 al 18; luego en 16 al 18; luego hoyo 18; luego mismo procedimiento para la vuelta del 1 al 9; finalmente comparación hoyo por hoyo del 18 hacia el 1. Si la ronda oficial es de 9 hoyos, se compara primero la ronda completa y, si continúa, se aplica el mismo método del día anterior."}, {"titulo": "Categorías con hándicap", "contenido": "En las categorías que se juegan con hándicap, los desempates se definen con el Score Neto para el Neto y con el Score Gross para el Gross. Los desempates se realizan utilizando la misma modalidad de juego (Stroke Play o Stableford)."}]', 1)
ON DUPLICATE KEY UPDATE
  section_type = 'accordion',
  content = '[{"titulo": "Desempate por el primer lugar", "contenido": "Se jugará en el campo iniciando en el hoyo que designe el Comité. Si hay triple empate o más, el primer lugar se decide por juego en el campo (sólo un ganador absoluto) y las posiciones siguientes por comparación de tarjetas. Si no hay luz natural o las condiciones climatológicas impiden jugar en el campo, el primer lugar se decide por comparación de tarjetas. Si la competencia es Gross y Neto, sólo el trofeo Gross procede a juego en el campo; el 1er lugar Neto se define por comparación de tarjetas."}, {"titulo": "Desempate por segundo lugar en adelante y corte (Regla 5A — comparación de tarjetas)", "contenido": "Gana el jugador con la mejor ronda del último día. Si persiste el empate: mejor score en los hoyos 10 al 18; luego en 13 al 18; luego en 16 al 18; luego hoyo 18; luego mismo procedimiento para la vuelta del 1 al 9; finalmente comparación hoyo por hoyo del 18 hacia el 1. Si la ronda oficial es de 9 hoyos, se compara primero la ronda completa y, si continúa, se aplica el mismo método del día anterior."}, {"titulo": "Categorías con hándicap", "contenido": "En las categorías que se juegan con hándicap, los desempates se definen con el Score Neto para el Neto y con el Score Gross para el Gross. Los desempates se realizan utilizando la misma modalidad de juego (Stroke Play o Stableford)."}]',
  enabled = 1,
  updated_at = CURRENT_TIMESTAMP;

INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (349, 'codigo_conducta', 'accordion', '[{"icon": "Trophy", "titulo": "Hole In One y O´yes", "contenido": "Habrá premios de Hole In One en los par 3: hoyos 3, 5, 7, 12 y 16. En caso de un segundo Hole In One en el mismo hoyo se considerará como el mejor O´yes a 0.0 metros; en un tercero, gana quien lo haga primero. Se premia el mejor O´yes general de cada par 3 de todo el torneo (en empate gana quien tiró primero). Las hojas firmadas por los jugadores confirmando la distancia de su bola al hoyo son inapelables; asegúrese antes de firmar."}, {"icon": "Wallet", "titulo": "Brazalete y registro diario", "contenido": "Es indispensable el registro diario en la recepción del Club para contar con el brazalete que da acceso al servicio de alimentos y bebidas. Deberá portarse en la muñeca sin excepción durante todo el torneo."}, {"icon": "ShieldAlert", "titulo": "Acceso a menores", "contenido": "Durante el desarrollo del Torneo queda restringido el acceso a menores de edad a la Casa Club, eventos sociales y premiación. Sólo se autoriza el acceso a menores que jueguen en la categoría Premier de Caballeros y 1ª Categoría de Damas."}, {"icon": "ScrollText", "titulo": "Tarjetas de score", "contenido": "Los jugadores son responsables de entregar sus tarjetas firmadas con el número de golpes sin ventaja (Gross) escritos claramente en cada hoyo de la tarjeta oficial. La tarjeta debe estar firmada por el anotador."}, {"icon": "Scale", "titulo": "Conducta deportiva", "contenido": "Se espera conducta deportiva ejemplar de todos los participantes. El Comité Organizador se reserva el derecho de hacer cualquier cambio que juzgue necesario para el mejor desarrollo del torneo; cualquier punto no previsto en la presente convocatoria será resuelto por el Comité y su decisión será inapelable."}]', 1)
ON DUPLICATE KEY UPDATE
  section_type = 'accordion',
  content = '[{"icon": "Trophy", "titulo": "Hole In One y O´yes", "contenido": "Habrá premios de Hole In One en los par 3: hoyos 3, 5, 7, 12 y 16. En caso de un segundo Hole In One en el mismo hoyo se considerará como el mejor O´yes a 0.0 metros; en un tercero, gana quien lo haga primero. Se premia el mejor O´yes general de cada par 3 de todo el torneo (en empate gana quien tiró primero). Las hojas firmadas por los jugadores confirmando la distancia de su bola al hoyo son inapelables; asegúrese antes de firmar."}, {"icon": "Wallet", "titulo": "Brazalete y registro diario", "contenido": "Es indispensable el registro diario en la recepción del Club para contar con el brazalete que da acceso al servicio de alimentos y bebidas. Deberá portarse en la muñeca sin excepción durante todo el torneo."}, {"icon": "ShieldAlert", "titulo": "Acceso a menores", "contenido": "Durante el desarrollo del Torneo queda restringido el acceso a menores de edad a la Casa Club, eventos sociales y premiación. Sólo se autoriza el acceso a menores que jueguen en la categoría Premier de Caballeros y 1ª Categoría de Damas."}, {"icon": "ScrollText", "titulo": "Tarjetas de score", "contenido": "Los jugadores son responsables de entregar sus tarjetas firmadas con el número de golpes sin ventaja (Gross) escritos claramente en cada hoyo de la tarjeta oficial. La tarjeta debe estar firmada por el anotador."}, {"icon": "Scale", "titulo": "Conducta deportiva", "contenido": "Se espera conducta deportiva ejemplar de todos los participantes. El Comité Organizador se reserva el derecho de hacer cualquier cambio que juzgue necesario para el mejor desarrollo del torneo; cualquier punto no previsto en la presente convocatoria será resuelto por el Comité y su decisión será inapelable."}]',
  enabled = 1,
  updated_at = CURRENT_TIMESTAMP;

